import pool from "../config/database.js";
import { sendTransactionalEmail } from "../services/emailTransport.service.js";

const VALID_STATUSES = new Set([
  "NEW",
  "READ",
  "RESPONDED",
  "CLOSED",
]);

const VALID_SUBJECTS = new Set([
  "QUOTE",
  "PRODUCT",
  "STOCK",
  "BUSINESS",
  "PROJECT",
  "OTHER",
]);

const SUBJECT_LABELS = {
  QUOTE: "Cotización",
  PRODUCT: "Consulta de producto",
  STOCK: "Disponibilidad / stock",
  BUSINESS: "Venta empresa",
  PROJECT: "Proyecto",
  OTHER: "Otro",
};

/* =========================================
   FIRMA CORPORATIVA EMAIL
   Imágenes embebidas directamente en este
   controlador para no depender de URLs
   externas ni archivos públicos.
========================================= */

const CONTACT_SIGNATURE_IMAGE_BASE64 =
  "";

const CONTACT_SIGNATURE_ATTACHMENTS = [
  {
    filename: "laminati-firma-corporativa.png",
    content: Buffer.from(
      CONTACT_SIGNATURE_IMAGE_BASE64,
      "base64"
    ),
    contentType: "image/png",
    cid: "laminati-corporate-signature",
  },
];

const normalizeText = (value) => String(value ?? "").trim();
const normalizeUpper = (value) => normalizeText(value).toUpperCase();

const isUuid = (value) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    String(value || "")
  );

const sendError = (res, error, fallbackMessage) => {
  const status = Number(error?.status) || 500;

  if (status >= 500) {
    console.error(fallbackMessage, error);
  }

  return res.status(status).json({
    success: false,
    message: error?.message || fallbackMessage,
    code: error?.code || "ADMIN_CONTACTS_ERROR",
  });
};

const createServiceError = (message, status = 400, code = null) => {
  const error = new Error(message);
  error.status = status;
  error.code = code;
  return error;
};

const isValidEmail = (value) =>
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizeText(value));

const escapeHtml = (value) =>
  normalizeText(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");

