export const listAdminContacts = async (req, res) => {
  try {
    const search = normalizeText(req.query.search).slice(0, 160);
    const status = normalizeUpper(req.query.status);
    const subject = normalizeUpper(req.query.subject);
    const page = Math.max(1, Number.parseInt(req.query.page, 10) || 1);
    const limit = Math.min(
      100,
      Math.max(1, Number.parseInt(req.query.limit, 10) || 20)
    );
    const offset = (page - 1) * limit;

    const params = [];
    const conditions = [];

    if (search) {
      params.push(`%${search}%`);
      conditions.push(`(
        first_name ILIKE $${params.length}
        OR last_name ILIKE $${params.length}
        OR email ILIKE $${params.length}
        OR COALESCE(company_name, '') ILIKE $${params.length}
        OR COALESCE(phone, '') ILIKE $${params.length}
        OR message ILIKE $${params.length}
        OR CONCAT_WS(' ', first_name, last_name) ILIKE $${params.length}
      )`);
    }

    if (status && status !== "ALL") {
      if (!VALID_STATUSES.has(status)) {
        throw createServiceError(
          "El estado seleccionado no es válido",
          400,
          "ADMIN_CONTACT_INVALID_STATUS"
        );
      }

      params.push(status);
      conditions.push(`status = $${params.length}`);
    }

    if (subject && subject !== "ALL") {
      if (!VALID_SUBJECTS.has(subject)) {
        throw createServiceError(
          "El motivo seleccionado no es válido",
          400,
          "ADMIN_CONTACT_INVALID_SUBJECT"
        );
      }

      params.push(subject);
      conditions.push(`subject = $${params.length}`);
    }

    const whereSql = conditions.length
      ? `WHERE ${conditions.join(" AND ")}`
      : "";

    const countResult = await pool.query(
      `
        SELECT COUNT(*)::int AS total
        FROM public.contact_messages
        ${whereSql}
      `,
      params
    );

    const total = Number(countResult.rows[0]?.total || 0);

    const listParams = [...params, limit, offset];
    const limitParam = `$${params.length + 1}`;
    const offsetParam = `$${params.length + 2}`;

    const listResult = await pool.query(
      `
        SELECT
          id,
          first_name,
          last_name,
          company_name,
          email,
          phone,
          subject,
          message,
          status,
          source,
          read_at,
          responded_at,
          created_at,
          updated_at
        FROM public.contact_messages
        ${whereSql}
        ORDER BY
          CASE status
            WHEN 'NEW' THEN 0
            WHEN 'READ' THEN 1
            WHEN 'RESPONDED' THEN 2
            ELSE 3
          END,
          created_at DESC
        LIMIT ${limitParam}
        OFFSET ${offsetParam}
      `,
      listParams
    );

    const summaryResult = await pool.query(
      `
        SELECT
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE status = 'NEW')::int AS new,
          COUNT(*) FILTER (WHERE status = 'READ')::int AS read,
          COUNT(*) FILTER (WHERE status = 'RESPONDED')::int AS responded,
          COUNT(*) FILTER (WHERE status = 'CLOSED')::int AS closed
        FROM public.contact_messages
      `
    );

    const summary = summaryResult.rows[0] || {
      total: 0,
      new: 0,
      read: 0,
      responded: 0,
      closed: 0,
    };

    return res.status(200).json({
      success: true,
      data: listResult.rows,
      summary: {
        total: Number(summary.total || 0),
        new: Number(summary.new || 0),
        read: Number(summary.read || 0),
        responded: Number(summary.responded || 0),
        closed: Number(summary.closed || 0),
      },
      pagination: {
        page,
        limit,
        total,
        total_pages: Math.max(1, Math.ceil(total / limit)),
      },
    });
  } catch (error) {
    return sendError(
      res,
      error,
      "No fue posible cargar las consultas de contacto"
    );
  }
};

export const updateAdminContactStatus = async (req, res) => {
  try {
    const messageId = req.params.messageId;
    const status = normalizeUpper(req.body?.status);

    if (!isUuid(messageId)) {
      throw createServiceError(
        "Consulta inválida",
        400,
        "ADMIN_CONTACT_INVALID_ID"
      );
    }

    if (!VALID_STATUSES.has(status)) {
      throw createServiceError(
        "El estado seleccionado no es válido",
        400,
        "ADMIN_CONTACT_INVALID_STATUS"
      );
    }

    const result = await pool.query(
      `
        WITH input AS (
          SELECT
            $1::uuid AS message_id,
            $2::varchar(20) AS next_status
        )
        UPDATE public.contact_messages AS cm
        SET
          status = input.next_status,
          read_at = CASE
            WHEN input.next_status = 'NEW' THEN NULL
            ELSE COALESCE(cm.read_at, NOW())
          END,
          responded_at = CASE
            WHEN input.next_status = 'RESPONDED'
              THEN COALESCE(cm.responded_at, NOW())
            WHEN input.next_status IN ('NEW', 'READ')
              THEN NULL
            ELSE cm.responded_at
          END,
          updated_at = NOW()
        FROM input
        WHERE cm.id = input.message_id
        RETURNING
          cm.id,
          cm.first_name,
          cm.last_name,
          cm.company_name,
          cm.email,
          cm.phone,
          cm.subject,
          cm.message,
          cm.status,
          cm.source,
          cm.read_at,
          cm.responded_at,
          cm.created_at,
          cm.updated_at
      `,
      [messageId, status]
    );

    if (result.rowCount === 0) {
      throw createServiceError(
        "La consulta no fue encontrada",
        404,
        "ADMIN_CONTACT_NOT_FOUND"
      );
    }

    return res.status(200).json({
      success: true,
      message: "Estado de la consulta actualizado correctamente",
      data: result.rows[0],
    });
  } catch (error) {
    return sendError(
      res,
      error,
      "No fue posible actualizar la consulta"
    );
  }
};
export const listAdminContactReplies = async (req, res) => {
  try {
    const messageId = req.params.messageId;

    if (!isUuid(messageId)) {
      throw createServiceError(
        "Consulta inválida",
        400,
        "ADMIN_CONTACT_INVALID_ID"
      );
    }

    const contactResult = await pool.query(
      `
        SELECT id
        FROM public.contact_messages
        WHERE id = $1::uuid
        LIMIT 1
      `,
      [messageId]
    );

    if (contactResult.rowCount === 0) {
      throw createServiceError(
        "La consulta no fue encontrada",
        404,
        "ADMIN_CONTACT_NOT_FOUND"
      );
    }

    const result = await pool.query(
      `
        SELECT
          r.id,
          r.contact_message_id,
          r.admin_user_id,
          r.recipient_email,
          r.subject,
          r.message,
          r.delivery_status,
          r.provider_message_id,
          r.error_message,
          r.sent_at,
          r.created_at,
          u.first_name AS admin_first_name,
          u.last_name AS admin_last_name,
          u.email AS admin_email
        FROM public.contact_message_replies r
        LEFT JOIN public.users u
          ON u.id = r.admin_user_id
        WHERE r.contact_message_id = $1::uuid
        ORDER BY r.created_at ASC, r.id ASC
      `,
      [messageId]
    );

    return res.status(200).json({
      success: true,
      data: result.rows,
    });
  } catch (error) {
    return sendError(
      res,
      error,
      "No fue posible cargar las respuestas de la consulta"
    );
  }
};

export const sendAdminContactReply = async (req, res) => {
  let replyId = null;

  try {
    const messageId = req.params.messageId;
    const adminUserId = req.user?.id;
    const subject = normalizeText(req.body?.subject).slice(0, 255);
    const message = normalizeText(req.body?.message).slice(0, 5000);

    if (!isUuid(messageId)) {
      throw createServiceError(
        "Consulta inválida",
        400,
        "ADMIN_CONTACT_INVALID_ID"
      );
    }

    if (!isUuid(adminUserId)) {
      throw createServiceError(
        "Usuario administrador inválido",
        401,
        "ADMIN_CONTACT_INVALID_ADMIN"
      );
    }

    if (subject.length < 2) {
      throw createServiceError(
        "El asunto de la respuesta es obligatorio",
        400,
        "ADMIN_CONTACT_REPLY_SUBJECT_REQUIRED"
      );
    }

    if (message.length < 2) {
      throw createServiceError(
        "El mensaje de respuesta es obligatorio",
        400,
        "ADMIN_CONTACT_REPLY_MESSAGE_REQUIRED"
      );
    }

    const contactResult = await pool.query(
      `
        SELECT
          id,
          first_name,
          last_name,
          company_name,
          email,
          phone,
          subject,
          message,
          status,
          source,
          read_at,
          responded_at,
          created_at,
          updated_at
        FROM public.contact_messages
        WHERE id = $1::uuid
        LIMIT 1
      `,
      [messageId]
    );

    if (contactResult.rowCount === 0) {
      throw createServiceError(
        "La consulta no fue encontrada",
        404,
        "ADMIN_CONTACT_NOT_FOUND"
      );
    }

    const contact = contactResult.rows[0];

    if (contact.status === "CLOSED") {
      throw createServiceError(
        "Reabre la consulta antes de enviar una nueva respuesta",
        409,
        "ADMIN_CONTACT_CLOSED"
      );
    }

    const recipientEmail = normalizeText(contact.email).toLowerCase();

    if (!isValidEmail(recipientEmail)) {
      throw createServiceError(
        "El correo del contacto no es válido",
        409,
        "ADMIN_CONTACT_INVALID_EMAIL"
      );
    }

    const pendingResult = await pool.query(
      `
        INSERT INTO public.contact_message_replies (
          contact_message_id,
          admin_user_id,
          recipient_email,
          subject,
          message,
          delivery_status
        )
        VALUES (
          $1::uuid,
          $2::uuid,
          $3::varchar(255),
          $4::varchar(255),
          $5::text,
          'PENDING'
        )
        RETURNING
          id,
          contact_message_id,
          admin_user_id,
          recipient_email,
          subject,
          message,
          delivery_status,
          provider_message_id,
          error_message,
          sent_at,
          created_at
      `,
      [
        messageId,
        adminUserId,
        recipientEmail,
        subject,
        message,
      ]
    );

    const pendingReply = pendingResult.rows[0];
    replyId = pendingReply.id;

    const emailContent = buildContactReplyEmail({
      contact,
      subject,
      message,
    });

    const fromAddress = normalizeText(process.env.EMAIL_FROM_ADDRESS);
    const messageDomain =
      fromAddress.includes("@")
        ? fromAddress.split("@").pop()
        : "laminatiword.local";

    const delivery = await sendTransactionalEmail({
      to: recipientEmail,
      subject,
      text: emailContent.text,
      html: emailContent.html,
      attachments:
        emailContent.attachments,
      messageId: `<contact-reply-${replyId}@${messageDomain}>`,
    });

    const rejected = Array.isArray(delivery?.rejected)
      ? delivery.rejected.map((value) => normalizeText(value).toLowerCase())
      : [];

    if (rejected.includes(recipientEmail)) {
      throw createServiceError(
        "El servidor de correo rechazó el destinatario",
        502,
        "ADMIN_CONTACT_REPLY_REJECTED"
      );
    }

    /*
     * El correo ya salió del sistema en este punto.
     * Primero dejamos la respuesta como SENT para que un
     * eventual error posterior al actualizar la consulta
     * no la marque falsamente como FAILED.
     */
    const sentResult = await pool.query(
      `
        UPDATE public.contact_message_replies
        SET
          delivery_status = 'SENT',
          provider_message_id = $2,
          error_message = NULL,
          sent_at = NOW()
        WHERE id = $1::uuid
        RETURNING
          id,
          contact_message_id,
          admin_user_id,
          recipient_email,
          subject,
          message,
          delivery_status,
          provider_message_id,
          error_message,
          sent_at,
          created_at
      `,
      [replyId, delivery?.message_id || null]
    );

    const updatedContactResult = await pool.query(
      `
        UPDATE public.contact_messages
        SET
          status = 'RESPONDED',
          read_at = COALESCE(read_at, NOW()),
          responded_at = NOW(),
          updated_at = NOW()
        WHERE id = $1::uuid
        RETURNING
          id,
          first_name,
          last_name,
          company_name,
          email,
          phone,
          subject,
          message,
          status,
          source,
          read_at,
          responded_at,
          created_at,
          updated_at
      `,
      [messageId]
    );

    return res.status(201).json({
      success: true,
      message: "Respuesta enviada correctamente",
      data: {
        reply: {
          ...sentResult.rows[0],
          admin_first_name: req.user?.first_name || null,
          admin_last_name: req.user?.last_name || null,
          admin_email: req.user?.email || null,
        },
        contact: updatedContactResult.rows[0],
      },
    });
  } catch (error) {
    if (replyId) {
      await pool
        .query(
          `
            UPDATE public.contact_message_replies
            SET
              delivery_status = 'FAILED',
              error_message = $2
            WHERE id = $1::uuid
              AND delivery_status = 'PENDING'
          `,
          [
            replyId,
            normalizeText(error?.message || "Error enviando correo").slice(
              0,
              1000
            ),
          ]
        )
        .catch((updateError) => {
          console.error(
            "No fue posible registrar el error de envío del contacto:",
            updateError
          );
        });
    }

    return sendError(
      res,
      error,
      "No fue posible enviar la respuesta"
    );
  }
};